const EMPTY_OBJ_TAGGED: &str = "{\"t\":\"obj\",\"entries\":[]}";

#[test]
fn differential_matches_ts_compat() {
    for case in cases() {
        let descriptor = decode(case.descriptor_tagged);
        let environment = decode(case.environment_tagged);
        let target = decode(case.target_tagged);
        let env = decode(EMPTY_OBJ_TAGGED);
        let installed = match installed_from_tree(&env, &target) {
            Ok(installed) => {
                assert_eq!(
                    None, case.ts_installed_error,
                    "{}: unexpected probe error",
                    case.id
                );
                installed
            }
            Err(err) => {
                assert_eq!(
                    Some(err.message.as_str()),
                    case.ts_installed_error,
                    "{}: probe error",
                    case.id
                );
                continue;
            }
        };
        let verdict = check_compatibility(&descriptor, &environment, &installed)
            .unwrap_or_else(|e| panic!("{}: shape error: {}", case.id, e.message));
        assert_eq!(
            verdict.compatible, case.ts_compatible,
            "{}: compatible",
            case.id
        );
        let reasons: Vec<(&str, &str)> = verdict
            .reasons
            .iter()
            .map(|r| (r.code.as_str(), r.detail.as_str()))
            .collect();
        assert_eq!(reasons, case.ts_reasons, "{}: reason order", case.id);
        let compiler = check_compiler_version_match(&descriptor, &installed)
            .unwrap_or_else(|e| panic!("{}: compiler shape error: {}", case.id, e.message));
        assert_eq!(
            compiler.is_none(),
            case.ts_compiler_none,
            "{}: compiler match",
            case.id
        );
        assert_eq!(
            compiler.as_deref(),
            case.ts_compiler_detail,
            "{}: compiler detail",
            case.id
        );
    }
}

#[test]
fn split_covers_both_sides() {
    let candidate: Vec<Vec<u16>> = vec![units("state"), units("mystery"), units("d1-batch")];
    let installed: Vec<Vec<u16>> = vec![
        units("state"),
        units("d1-batch"),
        units("ghost"),
        units("ghost"),
    ];
    let out = split_capabilities(&candidate, &installed);
    let render = |ids: Vec<Vec<u16>>| {
        ids.iter()
            .map(|u| String::from_utf16(u).unwrap())
            .collect::<Vec<_>>()
    };
    assert_eq!(render(out.installed), vec!["state", "d1-batch"]);
    assert_eq!(render(out.missing), Vec::<String>::new());
    assert_eq!(render(out.unknown), vec!["mystery", "ghost"]);
}

#[test]
fn probe_rejects_non_record_env() {
    let target = decode(cases()[0].target_tagged);
    let env = Node::Num {
        bits: 0,
        spelling: "0".to_string(),
    };
    let err = installed_from_tree(&env, &target).expect_err("non-record env must fail");
    assert_eq!(
        err.message,
        "probeInstalledRuntime needs the target env as a record"
    );
}
